// Fictional business profiles for the sample market. No real contact details.
const wholesalers=[
 {name:'Patil Fresh Traders',initials:'PF',address:'Shop 12, Shivaji Market, Camp',owner:'Suresh Patil',since:2014,hours:'5:00 AM – 2:00 PM',specialty:'Vegetables & fruits',delivery:'Morning delivery',area:'Camp · Swargate',rating:4.8,reviews:124,distance:1.2},
 {name:'Shree Ganesh Wholesale',initials:'SG',address:'Shop 28, Market Yard, Gultekdi',owner:'Meena Shah',since:2011,hours:'6:00 AM – 5:00 PM',specialty:'Vegetables',delivery:'Same-day delivery',area:'Camp · Gultekdi',rating:4.7,reviews:86,distance:2.1},
 {name:'Mahadev Market Supplies',initials:'MM',address:'Shop 7, Bhavani Peth Market',owner:'Anil Jadhav',since:2017,hours:'5:30 AM – 3:00 PM',specialty:'Vegetables',delivery:'Morning delivery',area:'Bhavani Peth · Camp',rating:4.9,reviews:203,distance:1.8},
 {name:'Deshmukh Grain House',initials:'DG',address:'Shop 41, Market Yard, Gultekdi',owner:'Asha Deshmukh',since:2008,hours:'8:00 AM – 6:00 PM',specialty:'Grains & pulses',delivery:'Next-day delivery',area:'Gultekdi · Swargate',rating:4.6,reviews:71,distance:3.4}
];
$('#wholesalerProfiles').innerHTML=wholesalers.map((w,i)=>`<article class="wholesaler-card"><div class="wholesaler-title"><span class="business-avatar">${w.initials}</span><div><h3>${w.name}</h3><span>★ ${w.rating} · ${w.reviews} reviews · ${w.distance} km away</span></div></div><p class="business-address">⌖ ${w.address}</p><dl><div><dt>Owner</dt><dd>${w.owner}</dd></div><div><dt>Established</dt><dd>${w.since}</dd></div><div><dt>Speciality</dt><dd>${w.specialty}</dd></div><div><dt>Business hours</dt><dd>${w.hours}</dd></div><div><dt>Delivery</dt><dd>${w.delivery}</dd></div><div><dt>Delivery area</dt><dd>${w.area}</dd></div></dl><button class="orderbtn" data-supplier-index="${i}">Browse stock →</button></article>`).join('');
$('#wholesalerProfiles').onclick=e=>{const b=e.target.closest('[data-supplier-index]');if(!b)return;category='All supplies';document.querySelector('[data-cat="All supplies"]').click();$('#search').value=wholesalers[Number(b.dataset.supplierIndex)].name;render();$('#search').focus();$('#cards').scrollIntoView({behavior:'smooth',block:'start'})};
